mapper.select:
select id, event_id as eventId, trace_id as traceId, request_id as requestId, user_id as userId, username, dept_name as deptName, title, business_type as businessType, api_path as apiPath, request_method as requestMethod, controller_method as controllerMethod, client_ip as clientIp, client_location as clientLocation, user_agent as userAgent, request_params as requestParams, response_body as responseBody, http_status as httpStatus, exec_status as execStatus, error_message as errorMessage, cost_time_ms as costTimeMs, occurred_at as occurredAt from log_operation_record
and username like concat('%', #{username}, '%')
and title like concat('%', #{title}, '%')
and api_path like concat('%', #{apiPath}, '%')
and (title like concat('%', #{keyword}, '%') or api_path like concat('%', #{keyword}, '%') or controller_method like concat('%', #{keyword}, '%'))
and exec_status = #{execStatus}
and occurred_at >= #{startTime}
and occurred_at <= #{endTime}
order by occurred_at desc

mapper.delete:
delete from log_operation_record
where occurred_at < #{cutoffTime}
order by occurred_at asc
limit #{limit}
